import React, { useState } from 'react';
import { Button, Alert, Card, Form, InputGroup } from 'react-bootstrap';
import { Zap, CheckCircle, XCircle } from 'lucide-react';

const InvoiceTest = () => {
  const [amount, setAmount] = useState(1000);
  const [description, setDescription] = useState("Test de facture");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const testInvoice = async () => {
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      console.log('Test de génération de facture...');

      const requestBody = {
        sats: parseInt(amount),
        description: description
      };

      console.log('Corps de la requête:', requestBody);

      const response = await fetch('http://localhost:5003/api/invoice', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(requestBody)
      });

      console.log('Statut de la réponse:', response.status, response.statusText);
      console.log('Headers de la réponse:', response.headers);

      const responseText = await response.text();
      console.log('Texte de la réponse:', responseText);

      if (!response.ok) {
        throw new Error(`Erreur ${response.status}: ${responseText}`);
      }

      let data;
      try {
        data = JSON.parse(responseText);
      } catch (parseError) {
        console.error('Erreur de parsing JSON:', parseError);
        throw new Error('Réponse invalide du serveur');
      }

      console.log('Données parsées:', data);
      setResult(data);

    } catch (err) {
      console.error('Erreur complète:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className="mt-4">
      <Card.Header className="bg-primary text-white">
        <h5 className="mb-0">Test de Génération de Facture</h5>
      </Card.Header>
      <Card.Body>
        <div className="mb-3">
          <label className="form-label">Montant (sats):</label>
          <InputGroup>
            <InputGroup.Text><Zap size={16} /></InputGroup.Text>
            <Form.Control
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              min="1"
            />
            <InputGroup.Text>sats</InputGroup.Text>
          </InputGroup>
        </div>

        <div className="mb-3">
          <label className="form-label">Description:</label>
          <Form.Control
            type="text"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
        </div>

        <Button 
          variant="success" 
          onClick={testInvoice}
          disabled={loading}
          className="w-100"
        >
          {loading ? 'Génération...' : 'Générer la facture'}
        </Button>

        {error && (
          <Alert variant="danger" className="mt-3">
            <XCircle className="me-2" size={20} />
            <strong>Erreur:</strong> {error}
          </Alert>
        )}

        {result && (
          <Alert variant="success" className="mt-3">
            <CheckCircle className="me-2" size={20} />
            <strong>Succès!</strong>
            <div className="mt-2">
              <small className="d-block">
                <strong>Payment Request:</strong>
              </small>
              <code className="d-block p-2 bg-light rounded text-break small">
                {result.payment_request || result.id || JSON.stringify(result)}
              </code>
            </div>
          </Alert>
        )}

        <div className="mt-3">
          <small className="text-muted">
            Ouvrez la console du navigateur (F12) pour voir les logs détaillés.
          </small>
        </div>
      </Card.Body>
    </Card>
  );
};

export default InvoiceTest;
